                {
                    Interval = TimeSpan.FromMilliseconds(200)
                };
                _windowsMediaSessionsDebouncedRefresh.Tick += (_, _) =>
                {
                    _windowsMediaSessionsDebouncedRefresh.Stop();
                    _ = RefreshWindowsMediaSessionComboAsync();
                };
            }

